# smoke-report-sales-excel.ps1 — live smoke test: Report → Sales → Excel
#
# Drives the running app through the full reporting path against the real local
# PostgreSQL database:
#   1. seeds one sale dated today (the report's default window is the last 30 days)
#   2. logs in, opens the Reports view
#   3. selects report type "Sales" and format "Excel", clicks Generate
#   4. asserts the status line reports a generated byte count
#   5. removes the seeded row again, so the database is left as it was found
#
# Requires: WinApp CLI 0.7+ (winapp), psql on PATH (or set $psql below), a local
# PostgreSQL 'bpro_max' database, and the 'testuser' / 'testpass' account.
#
# Usage: .\smoke-report-sales-excel.ps1

$ErrorActionPreference = 'Stop'
$psql = 'C:\Program Files\PostgreSQL\17\bin\psql.exe'

function Get-AppWindow {
    $wins = @(& winapp ui list-windows --json | ConvertFrom-Json)
    $wins | Where-Object { $_.processName -eq 'b-pro-max' -and $_.title -ne 'PopupHost' -and $_.hwnd -ne '0' } |
        Select-Object -First 1
}

function Ui([string[]]$WinAppArgs) {
    & winapp ui @WinAppArgs
    if ($LASTEXITCODE -ne 0) { throw "winapp ui $($WinAppArgs -join ' ') failed (exit $LASTEXITCODE)" }
}

# --- seed one sale dated today so the default 30-day window has a row to export ---
# Marker amount makes the cleanup below precise.
$marker = 987654.32
& $psql -h localhost -p 5432 -U postgres -d bpro_max -q -c @"
INSERT INTO sales (agent_id, sale_date, amount, commission, commission1, currency_type, currency_rate, status)
SELECT a.id, now(), ${marker}, 100, 50, 'THB', 1, 'Paid' FROM agents a ORDER BY a.id LIMIT 1;
"@ 2>&1 | Out-Null

$rows = & $psql -h localhost -p 5432 -U postgres -d bpro_max -t -A -c "SELECT count(*) FROM sales WHERE sale_date > now() - interval '30 days';"
Write-Host "sales rows in default 30-day window: $rows"

function Remove-SmokeRow {
    & $psql -h localhost -p 5432 -U postgres -d bpro_max -q -c "DELETE FROM sales WHERE amount = $marker;" 2>&1 | Out-Null
}

# --- launch + login ---
$launch = & winapp run . --detach --json | ConvertFrom-Json
$AppPid = [int]$launch.ProcessId
Start-Sleep -Seconds 8
$win = Get-AppWindow
if (-not $win) { throw 'App window not found' }
$hwnd = [string]$win.hwnd
Write-Host "app pid=$AppPid hwnd=$hwnd"

Ui @('set-value', 'UsernameBox', 'testuser', '-w', $hwnd) | Out-Null
Ui @('set-value', 'PasswordBox', 'testpass', '-w', $hwnd) | Out-Null
Ui @('invoke', 'LoginButton', '-w', $hwnd) | Out-Null
Start-Sleep -Seconds 2
Ui @('wait-for', 'AgentListTitle', '-t', '8000', '-w', $hwnd) | Out-Null
Write-Host "login OK"

# --- navigate to Reports ---
Ui @('invoke', 'NavReports', '-w', $hwnd) | Out-Null
Ui @('wait-for', 'ReportGenerateButton', '-t', '8000', '-w', $hwnd) | Out-Null
Write-Host "reports view loaded"

# --- pick Sales + Excel, then generate ---
# A closed ComboBox does not expose its items, so expand it first, then select.
Ui @('invoke', 'ReportTypeCombo', '-w', $hwnd) | Out-Null
Start-Sleep -Milliseconds 700
Ui @('invoke', 'ReportTypeSales', '-w', $hwnd) | Out-Null
Start-Sleep -Milliseconds 700
Ui @('invoke', 'ReportFormatCombo', '-w', $hwnd) | Out-Null
Start-Sleep -Milliseconds 700
Ui @('invoke', 'FormatExcel', '-w', $hwnd) | Out-Null
Start-Sleep -Milliseconds 700
Ui @('invoke', 'ReportGenerateButton', '-w', $hwnd) | Out-Null
Start-Sleep -Seconds 3

# --- read the status text ---
$status = (& winapp ui inspect --json -w $hwnd | Out-String)
$m = [regex]::Match($status, '"automationId"\s*:\s*"ReportStatus"[^}]*?"name"\s*:\s*"([^"]*)"')
if (-not $m.Success) {
    $m = [regex]::Match($status, '"name"\s*:\s*"([^"]*generated[^"]*)"')
}
$text = if ($m.Success) { $m.Groups[1].Value } else { '<status not found>' }
Write-Host "ReportStatus = '$text'"

# --- Export button must now be enabled ---
$exportEnabled = & winapp ui inspect --interactive --json -w $hwnd | Out-String
Write-Host "ExportButton present in tree: $($exportEnabled -match 'ReportExportButton')"

Write-Host ""
Remove-SmokeRow
Stop-Process -Id $AppPid -Force -ErrorAction SilentlyContinue

if ($text -match 'generated \((\d+) bytes\)') {
    $bytes = [int]$Matches[1]
    Write-Host "SMOKE RESULT: PASS - Excel export produced $bytes bytes"
} elseif ($text -match 'Error') {
    Write-Host "SMOKE RESULT: FAIL - $text"
    exit 1
} else {
    Write-Host "SMOKE RESULT: INCONCLUSIVE - status was '$text'"
    exit 1
}
